def reduce_by_key(pairs):
    # map 端本地预聚合：每个分区内先按 key 聚成局部结果
    local = {}
    for k, v in pairs:
        local[k] = local.get(k, 0) + v
    return local

def combine(locals):
    # reduce 端合并各分区局部结果
    out = {}
    for loc in locals:
        for k, v in loc.items():
            out[k] = out.get(k, 0) + v
    return out

pairs = [('a', 2), ('b', 1), ('a', 3)]
local = reduce_by_key(pairs)          # 单分区预聚合
result = combine([local])             # 合并
print(result)                         # {'a': 5, 'b': 1}
